// === Tab: mySketch ===
//for the #wccChallenge on the theme of 'cubism'  -----> code by Aaron Reuland
//My main inspiration here is the cubist work of Robert Delauney, particulary his 'windows' series.
//Started with a recursive function that just broke triangles into smaller triangles.
//Then I started filling the triangle with gradients and experimenting with different rules
// for how often to break down the triangle and how to choose the colors in any given triangle.
//I came up with four pallettes and accompanying rules that make very abstracted landscapes.

//Available at fx(hash): https://www.fxhash.xyz/generative/slug/simultaneous-thoughts-in-the-form-of-land


let maxDepth = 8
let colors, sceneChooser, w, maxW, shadeQ, maxColor, minColor, contin, texture

let palettes = [

	//forest?
	["#a7c6da", "#eefcce", "#edff71", "#f1db4b", "#9eb25d"],

	//sunset?
	['#fcdb88', '#ff9fb2', '#c5d9e2', '#0f69fa', '#a9abc7'],

	//sw town
	['#6AE9F8', '#6AE9F8', '#9871F3', '#E9B359', '#F5DD92', '#EBF577', '#FFFFFF'],

	//moody badlands
	['#dce1e5', '#879eb9', '#687178', '#ddbd92', '#ef9f95', '#ef9f95']

]

function setup() {
	w = max(windowWidth, windowHeight)
	maxW = max(windowWidth, windowHeight)
	createCanvas(windowWidth, windowHeight);
	blendMode(MULTIPLY)
	sceneChooser = floor(random(4))

	//****** set variable to 0-3 and uncomment to choose the scene *******
	//sceneChooser=1

	colors = palettes[sceneChooser]
	noStroke()

	//make texture optional?
	texture = createGraphics(windowWidth, windowHeight);
	texture.pixelDensity(1)
	texture.loadPixels();
	for (let x = 0; x <= width; x++) {
		for (let y = 0; y <= height; y += floor(random(0, 3))) {
			texture.set(x, y, color(0, noise(x / 50, y / 50, x * y / 50) * random([0, 20, 30])))
		}
	}
	texture.updatePixels();


	for (let x = 0; x < width; x += width / 6) {
		for (let y = 0; y < height; y += height / 6) {
			point1 = createVector(x, y)
			point2 = createVector(x + width / 6, y)
			point3 = createVector(x + width / 6, y + height / 6)
			point4 = createVector(x, y + height / 6)
			tridown(point1, point2, point3, 0, floor(random(4)))
			tridown(point1, point3, point4, 0, floor(random(4)))
		}
	}
	image(texture, 0, 0)
}

function tridown(pt1, pt2, pt3, depth, a) {
	let yAvg = constrain((pt1.y + pt2.y + pt3.y) / 3, 0, height)
	let xAvg = constrain((pt1.x + pt2.x + pt3.x) / 3, 0, width)
	let shader = noise(pt1.x / 200, pt1.y / 200)

	//	***** things to change for different modes***
	if (sceneChooser == 0) {
		//this maps the probabilty (from 0 to 1) of a shaded dark edge
		//shadeQ = map(yAvg, 0, height * .75, 0.01, 0.4)
		if (depth < 2 && depth < 5 && yAvg>height*0.25) {
			shadeQ = noise(yAvg / 200, depth)
		} else {
			shadeQ = 0
		}
		//this maps the probabilty (from 0 to 1) of a continuing to break down after a depth of 2
		contin = map(yAvg, 0, height, 0.05, 0.75)
		//these control the max and min colors chosen randomly from color array
		maxColor = map(yAvg, height, 0, colors.length, 1)
		minColor = map(yAvg, height, 0, 1, 0)
	}
	if (sceneChooser == 1) {
		let center = createVector(width / 2, height * 0.65)
		// if (dist(center.x, center.y, xAvg, yAvg) > w / 5.5 && dist(center.x, center.y, xAvg, yAvg) < w / 4.5 && depth<2) {
		// 	shadeQ = 1.0
		// } else {
		// 	shadeQ = 0.1
		// }
		if (depth < 2 && depth < 5 && dist(center.x, center.y, xAvg, yAvg) > w / 4) {
			shadeQ = noise(yAvg / 200, depth)
		} else {
			shadeQ = 0
		}

		if (dist(center.x, center.y, xAvg, yAvg) < w / 4) {
			contin = 0.3
		} else {
			contin = map(dist(center.x, center.y, xAvg, yAvg), w / 4, maxW * 0.65, 0.4, 0.7)
		}

		if (dist(center.x, center.y, xAvg, yAvg) < w / 4) {
			maxColor = 2
			minColor = 0
		} else {
			maxColor = constrain(map(dist(center.x, center.y, xAvg, yAvg), 0, maxW * 0.4, 2, 4), 0, colors.length)
			minColor = 1
		}
	}
	if (sceneChooser == 2) {
		let div = w / colors.length
		let nValue = noise(xAvg / div, yAvg / div, depth / 3)

		//	shadeQ = 0

			if (depth < 2 && depth < 5) {
			shadeQ = noise(yAvg / 200, depth)
		} else {
			shadeQ = 0
		}

		contin = nValue / 5
		maxColor = map(nValue, 0, 1, 0, colors.length)
		minColor = map(noise(xAvg / div + 0.5, yAvg / div + 0.5, depth / 3), 0, 1, 0, colors.length)
	}
	if (sceneChooser == 3) {
		var div = w / colors.length
		if (depth < 2 && depth < 5) {
			shadeQ = noise(yAvg / 200, depth)
		} else {
			shadeQ = 0
		}

		if (yAvg < (height * 0.5 + map(noise(xAvg/150), 0, 1, -height / 5, height / 5))) {
			contin = 0.4
			maxColor = map(noise(xAvg / (width / 20)), 0, 1, 0, 3)
			minColor = 0
		} else {
			contin=0.5
			maxColor = map(noise(xAvg, yAvg), 0, 1, 3, colors.length)
			minColor = 2
		}
	}

	//Dark gradient 'edges'

	if (shader < shadeQ && depth < 5) {
		push()
		let c1
		if(sceneChooser<3){
			blendMode(BLEND)
			c1 = color(50, 200)
		}
		else{
		c1 = color(0)
		}
		let c2 = color(255, 10)
		let m = p5.Vector.lerp(pt1, pt2, 0.5)
		coloring = drawingContext.createLinearGradient(pt3.x, pt3.y, m.x, m.y)
		coloring.addColorStop(0, c1)
		coloring.addColorStop(0.33, c2)
		drawingContext.fillStyle = coloring
		triangle(pt1.x, pt1.y, pt2.x, pt2.y, pt3.x, pt3.y)
		pop()
	}


	//set colors gradients && draw triangles

	let cc1 = floor(random(minColor, maxColor))
	let cc2 = floor(random(minColor, maxColor))
	let cc3 = floor(random(minColor, maxColor))
	var c1 = color(colors[cc1])
	var c2 = color(colors[cc2])
	let c3 = color(colors[cc3])
	c1.setAlpha(200)
	c2.setAlpha(180)
	c3.setAlpha(180)
	coloring = drawingContext.createLinearGradient(pt1.x, pt1.y, pt2.x, pt2.y)
	coloring.addColorStop(0, c1)
	coloring.addColorStop(0.33, c2)
	coloring.addColorStop(1, c3)
	drawingContext.fillStyle = coloring
	//fill(c)
	windowWidth, windowHeight

	noStroke()
	triangle(pt1.x, pt1.y, pt2.x, pt2.y, pt3.x, pt3.y)


	//continue to break down triangle in 3 possible ways
	let angleChoice = floor(noise(pt1.x + pt1.y, pt3.x + pt3.y) * 3)
	let continueQ = random()
	if (depth < maxDepth) {
		if (depth < 3 || continueQ < contin) {
			//move=floor(random(1, 2))
			move = 1
			if (angleChoice == 2) {
				let newP = p5.Vector.lerp(pt2, pt3, 0.5)
				tridown(pt1, pt2, newP, depth + 1, a + move)
				tridown(pt1, pt3, newP, depth + 1, a + move)
			}
			if (angleChoice == 0) {
				var newP = p5.Vector.lerp(pt1, pt3, 0.5)
				tridown(pt2, pt1, newP, depth + 1, a + move)
				tridown(pt2, pt3, newP, depth + 1, a + move)
			}
			if (angleChoice == 1) {
				var newP = p5.Vector.lerp(pt1, pt2, 0.5)
				tridown(pt3, pt1, newP, depth + 1, a + move)
				tridown(pt3, pt2, newP, depth + 1, a + move)
			}
		}
	}
}

